 import numpy as np,torch
 validate();parent.gt_guard();torch.set_num_threads(1);folder=D/'pilot_v1'/ds;out=P/ds;a=read(folder/'reporting_receipt.json');assert a['status']=='verified_whole128_Source_prompt_only_all_mask_input_arrays_and_means';assert a['metrics_sha256']==sha(folder/'metrics.json')and a['score_sha256']==sha(folder/'score_receipt.json');assert read(D/'GPU_exit.json')['code']==0;rr=read(folder/'metrics.json')['private_rows'];rep=read(out/'report.json');seal=read(folder/'sealed.json');assert len(rr)==len(seal['files'])==rep['queries']==rep['parents']==128
 for arm,m in rep['means'].items():
  for k,v in m.items():
   x=[row['values'][arm][k]for row in rr if row['values'][arm][k]is not None];assert(v is None and not x)or abs(v-float(np.mean(x)))<1e-12
