  costs.append(dict(anonymous_index=i,worker=e['worker'],native_frames=len(e['raw_mask_checkpoints']),image_encoder_calls=e['actual_image_encoder_calls'],strict_postprocess_calls=e['actual_strict_postprocess_calls'],memory_BF16_to_FP32_V_casts=e['actual_memory_BF16_to_FP32_V_projection_casts'],decode_and_provenance_seconds=e['decode_and_provenance_seconds'],request_seconds=e['request_wall_including_checkpoints_seconds'],checkpoint_IO_seconds=e['raw_checkpoint_IO_seconds'],nested_stages=e['nested_stage_seconds'],conditional_query_wall_seconds=e['conditional_query_wall_seconds'],resident_GPU_bytes=e['resident_GPU_bytes'],peak_query_GPU_bytes=e['peak_query_GPU_bytes'],inherited_Source_only_cost_fields=source_cost,original_ReferDINO_cost_not_charged_to_Source_Edge_branch=True))
