 (out/'ROOT_FINDINGS_v1.md').write_text(text);atomic(folder/'root_export_receipt_v1.json',dict(status='root_full_tube_single_expert_all_signed_tails_shortlong_actual_cost_analysis_complete',code_sha256=sha(Path(__file__)),audit_sha256=sha(folder/'reporting_receipt.json'),report_sha256=sha(out/'report.json'),findings_sha256=sha(out/'ROOT_FINDINGS_v1.md'),cost_sha256=sha(out/'actual_cost_summary_v1.json'),new_GT_scoring=0,new_model=0,new_tracking=0))
